#!/usr/bin/env python3
# Soil moisture sensor reader for Raspberry Pi Zero W
# Uses MCP3008 ADC over SPI to read soil moisture data

import spidev
import time

# Define SPI bus and device parameters
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000

# Function to initialize the SPI connection
def initialize_spi():
    """Opens and configures the SPI connection."""
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        return spi
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return None

# Function to read data from the MCP3008 ADC
def read_mcp3008(spi, channel):
    """Reads a single channel from the MCP3008 ADC."""
    if channel < 0 or channel > 7:
        raise ValueError("Invalid MCP3008 channel number")

    # Construct SPI message to read channel
    command = [0x01, (0x08 + channel) << 4, 0x00]
    try:
        response = spi.xfer2(command)
        adc_value = ((response[1] & 0x03) << 8) + response[2]
        return adc_value
    except Exception as e:
        print(f"Error reading MCP3008 channel {channel}: {e}")
        return None

# Function to convert raw ADC value to moisture percentage
def convert_to_percentage(raw_value):
    """Converts raw ADC value to soil moisture percentage."""
    if raw_value is None:
        return None
    return round((raw_value / 1023.0) * 100, 2)

# Main function to read and display soil moisture data
def main():
    """Main function to read and display soil moisture data."""
    spi_connection = initialize_spi()
    if spi_connection is None:
        print("Failed to initialize SPI. Exiting.")
        return

    try:
        print("Starting soil moisture reading sequence...")
        for _ in range(5):
            raw_value = read_mcp3008(spi_connection, 0)  # Read from channel 0
            moisture_percentage = convert_to_percentage(raw_value)

            if moisture_percentage is not None:
                print(f"Soil moisture level: {moisture_percentage}%")
            else:
                print("Failed to convert ADC value to percentage.")

            time.sleep(2)  # Wait 2 seconds

        print("Soil moisture reading sequence completed.")

    except KeyboardInterrupt:
        print("\nScript interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if spi_connection:
            spi_connection.close()
            print("SPI connection closed.")

# Run the main function
if __name__ == "__main__":
    main()

