#!/usr/bin/env python3
"""
Heart-rate monitoring script for Raspberry Pi using MAX30102 sensor.
Logs heart-rate data to a file and prints to console.
"""

import time
import datetime
import board
import busio
import adafruit_circuitpython_max30102

# Constants
LOG_FILE = "heart_rate_log.txt"
SLEEP_INTERVAL = 1  # seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the MAX30102 sensor."""
    try:
        return adafruit_circuitpython_max30102.MAX30102(i2c_bus, address=0x57)
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads heart-rate and SpO2 data from the sensor."""
    try:
        return sensor.heart_rate, sensor.oxygen_saturation
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def compute_heart_rate(ir_samples, red_samples):
    """Estimates heart rate using peak-counting on IR samples."""
    if ir_samples is None or red_samples is None:
        return None

    # Simple peak-counting (not a full analysis)
    peaks = [i for i, val in enumerate(ir_samples) if val > red_samples[i]]
    if not peaks:
        return 0  # No peaks, assume resting
    return sum(peaks) / len(peaks)  # Average of peak locations

def log_data(timestamp, heart_rate, spo2):
    """Logs the data to a file."""
    try:
        with open(LOG_FILE, "a") as logfile:
            logfile.write(f"{timestamp},{heart_rate},{spo2}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def print_data(heart_rate, spo2):
    """Prints the data to the console."""
    print(f"Heart Rate: {heart_rate:.2f} BPM, SpO2: {spo2:.2f}%")

def main():
    """Main function to run the heart-rate monitoring."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            # Read raw data from the sensor
            ir_samples, red_samples = sensor.samples

            # Compute heart rate
            heart_rate = compute_heart_rate(ir_samples, red_samples)

            # Get current timestamp
            timestamp = datetime.datetime.now().isoformat()

            # Log and print the data
            log_data(timestamp, heart_rate, sensor.oxygen_saturation)
            print_data(heart_rate, sensor.oxygen_saturation)

            time.sleep(SLEEP_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or the sensor object itself
        # as they are automatically garbage collected.
        print("Program finished.")

if __name__ == "__main__":
    main()

