#!/usr/bin/env python3

import picamera2
from pyzbar.pyzbar import decode
import time

def initialize_camera():
    """Initializes the CSI camera module."""
    try:
        camera = picamera2.Picamera2()
        config = camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
        camera.configure(config)
        camera.start()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        frame = camera.capture_array()
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes from a frame."""
    try:
        gray = frame[:, :, 0]  # Convert to grayscale (simplified)
        decoded_objects = decode(gray)
        return decoded_objects
    except Exception as e:
        print(f"Error decoding QR code: {e}")
        return []

def process_qr_code(decoded_objects):
    """Processes decoded QR codes."""
    if decoded_objects:
        print('Hello, World!')
    else:
        print('No QR code detected.')

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera()
    if camera is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        frame = capture_frame(camera)
        if frame is None:
            print("Frame capture failed. Exiting.")
            camera.close()
            return

        decoded_objects = decode_qr_code(frame)
        process_qr_code(decoded_objects)

    finally:
        camera.close()
        print("Camera resources released.")

if __name__ == "__main__":
    main()

