import face_recognition
import numpy as np
import cv2
from gpiozero import Button
import time
import os
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
BUTTON_PIN = 23
DATASET_DIR = "Dataset"
CAMERA_INDEX = 0
TOLERANCE = 0.6
DEBOUNCE_DELAY = 0.2
LOGGED_NAMES = {}
LAST_LOGGED_TIMES = {}

def load_known_faces(dataset_dir):
    """Loads known face encodings and names from the dataset directory."""
    try:
        known_face_encodings = []
        known_face_names = []

        for filename in os.listdir(dataset_dir):
            if filename.lower().endswith(('.jpg', '.jpeg', '.png')):  # Case-insensitive file extension check
                image_path = os.path.join(dataset_dir, filename)
                try:
                    image = face_recognition.load_image_file(image_path)
                    face_encodings = face_recognition.face_encodings(image)

                    if face_encodings:
                        known_face_encodings.append(face_encodings[0])
                        known_face_names.append(os.path.splitext(filename)[0]) # Extract name from filename
                    else:
                        logging.warning(f"No face found in {filename}, skipping.")

                except Exception as e:
                    logging.error(f"Error processing image {filename}: {e}")

        if not known_face_encodings:
            raise ValueError("No faces found in the dataset directory.")

        return known_face_encodings, known_face_names

    except FileNotFoundError:
        logging.error(f"Dataset directory not found: {DATASET_DIR}")
        raise
    except ValueError as e:
        logging.error(f"Error loading faces from dataset: {e}")
        raise
    except Exception as e:
        logging.error(f"Unexpected error during face loading: {e}")
        raise

def recognize_faces(frame, known_face_encodings, known_face_names):
    """Recognizes faces in a given frame."""
    face_locations = face_recognition.face_locations(frame)
    face_encodings = face_recognition.face_encodings(frame, face_locations)

    names = []
    for face_encoding in face_encodings:
        matches = face_recognition.compare_faces(known_face_encodings, face_encoding)
        face_distances = face_recognition.face_distance(known_face_encodings, face_encoding)
        best_match_index = np.argmin(face_distances)
        if matches[best_match_index] and face_distances[best_match_index] <= TOLERANCE:
            name = known_face_names[best_match_index]
        else:
            name = "Unknown"
        names.append(name)
    return list(zip(face_locations, names))


def display_and_report(frame, face_locations_names, logged_names, last_logged_times, button):
    """Displays recognized faces and prints access logs."""

    current_time = time.time()
    for (top, right, bottom, left), name in face_locations_names:
        cv2.rectangle(frame, (left, bottom - 35), (right, bottom), (0, 0, 255), cv2.FILLED)
        font = cv2.FONT_HERSHEY_DUPLEX
        cv2.putText(frame, name, (left + 6, bottom - 6), font, 1.0, (255, 255, 255), 1)

        if name != "Unknown":
            if name not in logged_names or current_time - last_logged_times[name] > 5:
                logging.info(f"{name} was here")
                last_logged_times[name] = current_time

    cv2.imshow('Video', frame)
    if button.is_pressed:
        logging.info('Exit')
        return False
    return True


def main():
    """Main function to run the face recognition program."""
    try:
        button = Button(BUTTON_PIN, bounce_time=DEBOUNCE_DELAY)
        logging.info("Waiting for button press...")
        button.wait_for_press()
        logging.info("Button pressed!")

        known_face_encodings, known_face_names = load_known_faces(DATASET_DIR)

        try:
            video_capture = cv2.VideoCapture(CAMERA_INDEX)
            if not video_capture.isOpened():
                raise IOError("Cannot open webcam")
        except IOError as e:
            logging.error(f"Error opening video capture: {e}")
            return

        while True:
            ret, frame = video_capture.read()
            if not ret:
                logging.error("Failed to grab frame")
                break

            face_locations_names = recognize_faces(frame, known_face_encodings, known_face_names)
            if display_and_report(frame, face_locations_names, LOGGED_NAMES, LAST_LOGGED_TIMES, button):
                break

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

        video_capture.release()
        cv2.destroyAllWindows()

    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

