import serial
import time
import logging

# Configure logging for debugging and error tracking
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the Bluetooth serial port and baud rate
BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400

# Initialize the serial connection
try:
    bluetooth_serial = serial.Serial(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE, timeout=1)
    logging.info(f"Connected to Bluetooth serial port: {BLUETOOTH_PORT}")
except serial.SerialException as e:
    logging.error(f"Error opening serial port: {e}")
    exit(1)

def send_command(command):
    """Sends a formatted command over the Bluetooth serial connection."""
    try:
        full_command = 'X{0}'.format(command)
        encoded_command = full_command.encode("utf-8")
        bluetooth_serial.write(encoded_command)
        logging.info(f"Sent command: {full_command}")
        return True
    except serial.SerialException as e:
        logging.error(f"Error writing to serial port: {e}")
        return False
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        return False

def main():
    """Main function to continuously prompt for user input and send commands."""
    try:
        while True:
            try:
                user_input = input("Enter command (or 'q' to quit): ")
                if user_input.lower() == 'q':
                    break
                if send_command(user_input):
                    pass  # Command sent successfully, no action needed
                else:
                    logging.error("Command transmission failed.")

            except KeyboardInterrupt:
                logging.info("Exiting program.")
                break
            except Exception as e:
                logging.error(f"An unexpected error occurred: {e}")
                break
    finally:
        # Ensure the serial port is closed on exit
        if 'bluetooth_serial' in locals() and bluetooth_serial.is_open:
            bluetooth_serial.close()
            logging.info("Serial port closed.")

if __name__ == "__main__":
    main()

