import cv2
import numpy as np
import time
from picamera2 import Picamera2

# Constants
IMAGE_DIR = "images"
NUM_PICTURES = 5
CAMERA_INDEX = 0
RETRY_ATTEMPTS = 3
DELAY_SECONDS = 1

def ensure_directory_exists(directory):
    """Create the given directory if it doesn't exist."""
    try:
        import os
        os.makedirs(directory, exist_ok=True)
    except Exception as e:
        print(f"Error creating directory {directory}: {e}")
        raise

def initialize_camera(camera_index, retry_attempts):
    """Initialize the Picamera2 camera with retry logic."""
    for attempt in range(retry_attempts):
        try:
            picam2 = Picamera2(camera_index)
            picam2.configure(picam2.create_preview_configuration())
            picam2.start()
            return picam2
        except Exception as e:
            print(f"Camera initialization attempt {attempt + 1} failed: {e}")
            time.sleep(DELAY_SECONDS)
    return None

def detect_faces(frame, face_detector):
    """Detect faces in a given frame using the provided Haar cascade classifier."""
    gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return face_detector.detectMultiScale(gray_frame, scaleFactor=1.1, minNeighbors=5)

def draw_face_rectangles(frame, faces):
    """Draw rectangles around detected faces in the frame."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

def save_image(frame, image_directory, sequence_number):
    """Save the captured image to the specified directory with a sequence number."""
    try:
        filename = f"{image_directory}/image_{sequence_number}.jpg"
        cv2.imwrite(filename, frame)
        print(f"Saved image: {filename}")
        return True
    except Exception as e:
        print(f"Error saving image: {e}")
        return False

def main():
    """Main function to capture face images."""
    name = input("What is your name? ").strip().title()
    image_directory = f"./images/{name}"
    ensure_directory_exists(image_directory)

    picam2 = initialize_camera(CAMERA_INDEX, RETRY_ATTEMPTS)
    if picam2 is None:
        print("Failed to initialize camera after multiple attempts. Exiting.")
        return

    try:
        face_detector = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        sequence_number = 0

        while sequence_number < NUM_PICTURES:
            frame = picam2.capture_array()
            faces = detect_faces(frame, face_detector)

            if len(faces) > 0:
                draw_face_rectangles(frame, faces)
                if input("Press 'y' to capture this image, or any other key to skip: ").lower() == 'y':
                    if save_image(frame, image_directory, sequence_number):
                        sequence_number += 1
            elif input("No face detected. Press 'y' to try again, or any other key to skip: ").lower() != 'y':
                break # Exit loop if no face is detected and user doesn't want to retry

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        picam2.stop()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

