    """Initializes the I2C bus."""
    try:
        bus = smbus2.SMBus(bus_number)
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def read_cpu_temperature():
    """Reads the CPU temperature from the Raspberry Pi."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            temp_millidegrees = int(f.read())
            temp_celsius = temp_millidegrees / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print("Error: Could not find CPU temperature file.")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def display_temperature_on_oled(oled_address, temperature):
    """Displays the temperature on the OLED screen (not implemented)."""
    # This function would normally use smbus2 to send commands to the OLED
    # and update the display with the given temperature value.
    # For simplicity, we'll just print it to the console.
    print(f"Displaying temperature: {temperature:.2f} °C")

def main():
    """Main function to read and display CPU temperature."""
    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)

    if i2c_bus is None:
        print("Failed to initialize I2C bus. Exiting.")
        return

    try:
        while True:
            temperature = read_cpu_temperature()

            if temperature is not None:
