import spidev
import time

# SPI configuration for the MAX7219 LED matrix driver
SPI_BUS = 0
SPI_DEVICE = 0
SPI_CE_PIN = 8
SPI_MOSI_PIN = 10
SPI_SCLK_PIN = 11

# Initialize the SPI bus
spi_bus = spidev.SpiDev()

def open_spi_bus():
    """Open the SPI bus and return the SPI device object."""
    try:
        spi_bus.open(SPI_BUS, SPI_DEVICE)
        spi_bus.max_speed_hz = 1000000  # 1 MHz SPI clock
        return spi_bus
    except Exception as e:
        print(f"Error opening SPI bus: {e}")
        return None

def close_spi_bus(spi_device):
    """Close the SPI bus."""
    try:
        spi_device.close()
    except Exception as e:
        print(f"Error closing SPI bus: {e}")

def send_register_value(spi_device, register_address, data_value):
    """Send a byte of data to a specific register on the MAX7219."""
    try:
        spi_device.xfer2([register_address, data_value])
    except Exception as e:
        print(f"Error writing to register {register_address}: {e}")

def build_matrix_frame(alert_level):
    """Build an 8x8 matrix frame based on the alert level."""
    frame_data = [0x00] * 8  # Initialize all rows to off
    for row_index in range(alert_level):
        frame_data[row_index] = 0xFF  # Turn on all bits in the row
    return frame_data

def visualize_alert(spi_device, alert_level):
    """Visualize the alert level on the LED matrix."""
    try:
        matrix_frame = build_matrix_frame(alert_level)
        for row_index, data_value in enumerate(matrix_frame):
            send_register_value(spi_device, 0x01 + row_index, data_value)  # Send data to each row
        print(f"Alert level {alert_level}: matrix updated")
    except Exception as e:
