#!/usr/bin/env python3
# Predictive maintenance for a Raspberry Pi wearable device
# Author: Bard
# Date: October 26, 2023

import time
import random
import math
import logging
import sqlite3
from gpiozero import LED

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup (BCM numbering)
try:
    status_led = LED(23)
    logging.info("GPIO setup complete")
except Exception as e:
    logging.error(f"GPIO setup failed: {e}")
    status_led = None  # Disable LED functionality if GPIO fails

# Database setup
DATABASE_PATH = '/tmp/wearable_health.db'
try:
    conn = sqlite3.connect(DATABASE_PATH)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS alerts (
            remaining_life REAL,
            ts REAL
        )
    ''')
    conn.commit()
    logging.info("Database connection established")
except Exception as e:
    logging.error(f"Database connection failed: {e}")
    conn = None

# Sensor data storage
vibration_window = []
temperature_window = []

def read_vibration():
    """Simulate reading vibration data."""
    return random.uniform(0.1, 0.9)

def read_temperature():
    """Simulate reading temperature data."""
    return random.uniform(30.0, 70.0)

def compute_degradation_score(vibration_window, temperature_window):
    """Compute a degradation score from vibration and temperature windows."""
    if not vibration_window:
        return 0.0
    if not temperature_window:
        return 0.0
    mean_vibration = sum(vibration_window) / len(vibration_window)
    mean_temperature = sum(temperature_window) / len(temperature_window)
    return 0.6 * mean_vibration + 0.4 * (mean_temperature / 100.0)

def estimate_remaining_life(degradation_score):
    """Estimate remaining useful life in hours based on degradation score."""
    return max(0, 500 * math.exp(-3 * degradation_score))

def log_alert(remaining_life):
    """Log an alert and store it in the database."""
    if conn:
        try:
            cursor.execute("INSERT INTO alerts (remaining_life, ts) VALUES (?, ?)", (remaining_life, time.time()))
            conn.commit()
            logging.warning(f"Predictive maintenance alert: Remaining life {remaining_life:.2f} hours")
        except Exception as e:
            logging.error(f"Database insertion failed: {e}")

def main():
    """Main program loop for predictive maintenance."""
    try:
        for i in range(30):
            # Read sensor data
            vibration = read_vibration()
            temperature = read_temperature()

            # Store sensor data
            vibration_window.append(vibration)
            temperature_window.append(temperature)
            if len(vibration_window) > 20:
                vibration_window.pop(0)
            if len(temperature_window) > 20:
                temperature_window.pop(0)

            # Compute degradation score
            degradation_score = compute_degradation_score(vibration_window, temperature_window)

            # Estimate remaining useful life
            remaining_life = estimate_remaining_life(degradation_score)

            # Check for alert condition
            if remaining_life < 100:
                log_alert(remaining_life)
                if status_led:
                    status_led.blink(on_time=1, off_time=1)
            else:
                if status_led:
                    status_led.off()

            # Wait before next iteration
            time.sleep(0.05)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Cleanup resources
        if status_led:
            status_led.off()
        if conn:
            conn.close()
            logging.info("Database connection closed")
        logging.info("Program exiting")

if __name__ == "__main__":
    main()

