# Script Name: cpu_temperature_monitor.py
# Description: Reads and displays the CPU temperature on a Raspberry Pi.
# Author: Bard
# Date: 2023-10-27

import time
import os
from gpiozero import CPUTemperature

def read_cpu_temperature():
    """Reads the CPU temperature and returns it as a float.

    Returns:
        float: The CPU temperature in degrees Celsius.
        None: If the temperature cannot be read.

    Raises:
        FileNotFoundError: If the temperature file does not exist.
    """
    try:
        temp_sensor = CPUTemperature()  # Lazy instantiation
        temperature = temp_sensor.temperature
        return temperature
    except FileNotFoundError:
        print("Error: /sys/class/thermal/thermal_zone0/temp not found. Is this running on a Raspberry Pi?")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

def main():
    """Main function to continuously read and print the CPU temperature."""
    try:
        while True:
            temperature = read_cpu_temperature()

            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f} °C")
            else:
                print("Failed to read CPU temperature.")

            time.sleep(5)  # Wait 5 seconds

    except KeyboardInterrupt:
        print("\nProgram terminated.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

