# bmp280_altitude_logging_procedural.py
# Reads pressure and altitude from a BMP280 sensor over I2C and logs data to a file.
# Designed for Raspberry Pi 3, 4, and 5.

import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_BUS = 1
SCL_PIN = board.SCL
SDA_PIN = board.SDA
SENSOR_ADDRESS = 0x76  # Default address, SDO tied to GND
SEA_LEVEL_PRESSURE = 1013.25  # hPa
LOG_FILE = 'altitude_log.txt'
READ_INTERVAL_SECONDS = 1


def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(SCL_PIN, SDA_PIN)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=SENSOR_ADDRESS)
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None


def read_sensor_data(sensor):
    """Reads pressure and altitude from the BMP280 sensor."""
    try:
        pressure = sensor.pressure
        altitude = sensor.altitude
        return pressure, altitude
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None


def log_data(pressure, altitude, log_file):
    """Logs the pressure and altitude data to a file."""
    try:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"{timestamp} - Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n"
        with open(log_file, 'a') as file:
            file.write(log_entry)
        return True
    except Exception as e:
        print(f"Error writing to log file: {e}")
        return False


def main():
    """Main function to read and log sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    sensor = initialize_bmp280(i2c_bus)
    if sensor is None:
        return  # Exit if sensor initialization failed

    sensor.sea_level_pressure = SEA_LEVEL_PRESSURE

    try:
        while True:
            pressure, altitude = read_sensor_data(sensor)
            if pressure is not None and altitude is not None:
                print(f"Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters")
                if log_data(pressure, altitude, LOG_FILE):
                    print("Data logged successfully.")
                else:
                    print("Failed to log data.")
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # No specific cleanup needed for I2C or BMP280 libraries in this context,
        # but including a placeholder for potential future expansion.
        print("Exiting program.")


if __name__ == "__main__":
    main()

