#!/usr/bin/env python3

"""
Raspberry Pi UPS Plus Demo Code (Intermediate - Functional)

This script reads various parameters from the UPS Plus device and two INA219 sensors
connected to it, providing a functional approach with enhanced error handling and resource management.

Author: D. Scott Williamson (modified by Bard)
Date: 2023-11-20
License: This code and documentation are provided without warranty.
         Use at your own risk.
"""

import time
import smbus2
import logging
from ina219 import INA219, DeviceRangeError
from typing import Optional, Tuple, List

# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
DEVICE_BUS = 1  # I2C bus number
DEVICE_ADDRESS = 0x17  # I2C address of the UPS Plus device
SUPPLY_INA219_ADDRESS = 0x40  # I2C address of the INA219 sensor for Raspberry Pi power supply
BATTERY_INA219_ADDRESS = 0x45  # I2C address of the INA219 sensor for battery
SHUNT_RESISTOR_SUPPLY = 0.00725 # Shunt resistor value for supply current measurement
SHUNT_RESISTOR_BATTERY = 0.005  # Shunt resistor value for battery current measurement

# Register Map (UPS Plus)
REG_WH = 0x00
REG_VOLT_BUS = 0x02
REG_CURRENT_BUS = 0x04
REG_POWER_BUS = 0x06
REG_VOLT_BAT = 0x08
REG_CURRENT_BAT = 0x0A
REG_POWER_BAT = 0x0C
REG_VOLT_TYPEC = 0x0E
REG_VOLT_MICRO = 0x10
REG_CURRENT_TYPEC = 0x12
REG_CURRENT_MICRO = 0x14
REG_POWER_TYPEC = 0x16
REG_POWER_MICRO = 0x18
REG_BATTERY_TEMP = 0x1A
REG_STATUS = 0x1B
REG_SAMPLE_TIME = 0x1C
REG_LED_CTRL = 0x1D


def safe_read_register(bus: smbus2.SMBus, address: int, register: int, length: int) -> Optional[List[int]]:
    """Reads data from a register with error handling."""
    try:
        return bus.read_i2c_block_data(address, register, length)
    except OSError as e:
        logging.error(f"Error reading register 0x{register:02X} at address 0x{address:02X}: {e}")
        return None


def read_power_supply_data(ina: INA219, shunt_resistor: float) -> Optional[Tuple[float, float, float]]:
    """Reads and validates power supply data from INA219."""
    try:
        supply_voltage = ina.voltage()
        supply_current = ina.current()
        supply_power = ina.power()

        if not (11.0 <= supply_voltage <= 14.0):
            logging.warning("Supply voltage out of range: %f V", supply_voltage)
            return None
        if not (0.1 <= supply_current <= 5.0):
            logging.warning("Supply current out of range: %f mA", supply_current)
            return None
        if not (40.0 <= supply_power <= 120.0):
            logging.warning("Supply power out of range: %f mW", supply_power)
            return None

        return supply_voltage, supply_current, supply_power
    except DeviceRangeError:
        logging.warning("INA219 Device Range Error: Value out of range.")
        return None
    except Exception as e:
        logging.error(f"Error reading supply data: {e}")
        return None



def read_battery_data(ina: INA219, shunt_resistor: float) -> Optional[Tuple[float, float, float]]:
    """Reads and validates battery data from INA219."""
    try:
        battery_voltage = ina.voltage()
        battery_current = ina.current()
        battery_power = ina.power()

        if not (11.0 <= battery_voltage <= 14.0):
            logging.warning("Battery voltage out of range: %f V", battery_voltage)
            return None

        if battery_current > 0:
            if not (0.1 <= battery_current <= 2.0):
                logging.warning("Battery current (charging) out of range: %f mA", battery_current)
                return None
            if not (40.0 <= battery_power <= 120.0):
                logging.warning("Battery power (charging) out of range: %f mW", battery_power)
                return None
        else:  # Discharging
            if not (0.01 <= abs(battery_current) <= 2.0):
                logging.warning("Battery current (discharging) out of range: %f mA", abs(battery_current))
                return None
            if not (10.0 <= battery_power <= 100.0):
                logging.warning("Battery power (discharging) out of range: %f mW", battery_power)
                return None

        return battery_voltage, battery_current, battery_power
    except DeviceRangeError:
        logging.warning("INA219 Device Range Error: Value out of range.")
        return None
    except Exception as e:
        logging.error(f"Error reading battery data: {e}")
        return None


def read_ups_data(bus: smbus2.SMBus) -> Optional[List[Optional[int]]]:
    """Reads data from the UPS Plus device via I2C."""
    data: List[Optional[int]] = []
    safe_read_register(bus, DEVICE_ADDRESS, REG_WH, 2)  # WH already read in init

    for i in range(5):
        val = safe_read_register(bus, DEVICE_ADDRESS, REG_VOLT_BUS + 2 * i, 2)
        if val:
            data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_CURRENT_BUS, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_POWER_BUS, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    for i in range(3):
        val = safe_read_register(bus, DEVICE_ADDRESS, REG_VOLT_BAT + 2 * i, 2)
        if val:
            data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_CURRENT_BAT, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_POWER_BAT, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    for i in range(2):
        val = safe_read_register(bus, DEVICE_ADDRESS, REG_VOLT_TYPEC + 2 * i, 2)
        if val:
            data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_CURRENT_TYPEC, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_POWER_TYPEC, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_VOLT_MICRO, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_CURRENT_MICRO, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_POWER_MICRO, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_BATTERY_TEMP, 2)
    if val:
        data.append(val[1] << 8 | val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_STATUS, 1)
    if val:
        data.append(val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_SAMPLE_TIME, 1)
    if val:
        data.append(val[0])

    val = safe_read_register(bus, DEVICE_ADDRESS, REG_LED_CTRL, 1)
    if val:
        data.append(val[0])

    return data


def initialize_ina219_sensor(shunt_resistor: float, bus_num: int, address: int) -> Optional[INA219]:
    """Initializes an INA219 sensor with error handling."""
    try:
        ina = INA219(shunt_resistor, busnum=bus_num, address=address)
        ina.configure()
        return ina
    except Exception as e:
        logging.error(f"Failed to initialize INA219 sensor at address 0x{address:02X}: {e}")
        return None


def main() -> None:
    """Main entry point for the UPS Plus demo code."""
    # Initialize the I2C bus.  The UPS Plus and INA219 sensors all reside on I2C bus 1.
    try:
        bus = smbus2.SMBus(DEVICE_BUS)
    except OSError as e:
        logging.error(f"Failed to open I2C bus {DEVICE_BUS}: {e}")
        return

    # Initialize the INA219 sensors.  Return None if initialization fails.
    ina_supply = initialize_ina219_sensor(SHUNT_RESISTOR_SUPPLY, DEVICE_BUS, SUPPLY_INA219_ADDRESS)
    ina_battery = initialize_ina219_sensor(SHUNT_RESISTOR_BATTERY, DEVICE_BUS, BATTERY_INA219_ADDRESS)

    if ina_supply is None or ina_battery is None:
        logging.error("One or more INA219 sensors failed to initialize. Exiting.")
        return

    try:
        while True:
            # Read and print power supply data.
            supply_data = read_power_supply_data(ina_supply, SHUNT_RESISTOR_SUPPLY)
            if supply_data:
                supply_voltage, supply_current, supply_power = supply_data
                logging.info("Raspberry Pi power supply voltage: %.3f V", supply_voltage)
                logging.info("Raspberry Pi power supply current: %.3f mA", supply_current)
                logging.info("Raspberry Pi power supply power: %.3f mW", supply_power)

            # Read and print battery data.
            battery_data = read_battery_data(ina_battery, SHUNT_RESISTOR_BATTERY)
            if battery_data:
                battery_voltage, battery_current, battery_power = battery_data
                logging.info("Batteries voltage: %.3f V", battery_voltage)

                if battery_current > 0:
                    logging.info("Battery current (charging): %.3f mA", battery_current)
                    logging.info("Battery power (charging): %.3f mW", battery_power)
                else:
                    logging.info("Battery current (discharging): %.3f mA", battery_current)
                    logging.info("Battery power (discharging): %.3f mW", battery_power)

            # Read all data from the UPS Plus device.
            ups_data = read_ups_data(bus)
            if ups_data:
                # Display UPS Plus data
                logging.info("Current WH: %d", ups_data[0])

                for i in range(5):
                    if ups_data[2 * i + 1] is not None:
                        voltage = ups_data[2 * i + 1]
                        logging.info("Voltage %d: %.3f mV", i + 1, voltage)
                    else:
                        logging.info("Voltage %d: N/A", i + 1)

                if ups_data[5] is not None:
                    current = ups_data[5]
                    logging.info("Current (bus): %.3f mA", current)
                else:
                    logging.info("Current (bus): N/A")

                if ups_data[7] is not None:
                    power = ups_data[7]
                    logging.info("Power (bus): %.3f mW", power)
                else:
                    logging.info("Power (bus): N/A")

                for i in range(3):
                    if ups_data[2 * i + 8] is not None:
                        voltage = ups_data[2 * i + 8]
                        logging.info("Battery Voltage %d: %.3f mV", i + 1, voltage)
                    else:
                        logging.info("Battery Voltage %d: N/A", i + 1)

                if ups_data[11] is not None:
                    current = ups_data[11]
                    logging.info("Current (battery): %.3f mA", current)
                else:
                    logging.info("Current (battery): N/A")

                if ups_data[13] is not None:
                    power = ups_data[13]
                    logging.info("Power (battery): %.3f mW", power)
                else:
                    logging.info("Power (battery): N/A")

