#!/usr/bin/env python3

import gpiozero
import time
import signal
import sys

# Define GPIO pins for the sensors (BCM numbering)
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1  # seconds

# Initialize GPIO resources
gpio_resources = []

def initialize_gpio():
    """Initialize GPIO pins as input with pull-up resistors."""
    global gpio_resources
    try:
        for pin in SENSOR_PINS:
            sensor = gpiozero.DigitalInputDevice(pin, pull_up=True)
            gpio_resources.append(sensor)
        print("GPIO resources initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def read_sensor_states():
    """Read the current state of each sensor."""
    sensor_states = []
    for sensor in gpio_resources:
        try:
            sensor_states.append(sensor.is_active)
        except Exception as e:
            print(f"Error reading sensor {sensor.pin}: {e}")
            sensor_states.append(False)  # Default to inactive on error
    return sensor_states

def process_sensor_responses(sensor_states):
    """Process sensor responses based on active state."""
    responses = []
    for i, is_active in enumerate(sensor_states):
        if is_active:
            if i == 0:
                responses.append('Response for sensor 1')
            elif i == 1:
                responses.append('Response for sensor 2')
            elif i == 2:
                responses.append('Response for sensor 3')
    return responses

def print_responses(responses):
    """Print the sensor responses."""
    if responses:
        print("Responses:")
        for response in responses:
            print(f"- {response}")

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        for sensor in gpio_resources:
            sensor.close()
        print("GPIO resources released.")
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")

def signal_handler(sig, frame):
    """Handle signals for graceful shutdown."""
    print("\nExiting program...")
    cleanup_gpio()
    sys.exit(0)

def main():
    """Main function to run the sensor monitoring loop."""
    initialize_gpio()

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Monitoring sensor responses...")
    print(f"Polling every {POLL_INTERVAL} seconds.")

    try:
        while True:
            sensor_states = read_sensor_states()
            responses = process_sensor_responses(sensor_states)
            print_responses(responses)
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

