PROMPT = "JAYES@ROVER53:\t"
RECEIVE_INTERVAL_MS = 100  # 100ms

# Configuration
GPIO.setwarnings(False)
GPIO.setmode(GPIO.BCM)

# Global State (using a dictionary for immutability within functions)
SERVER_STATE = {"is_running": False, "log_file_path": DEFAULT_LOG_FILE}


def get_server_state():
    """Returns a copy of the server state."""
    return SERVER_STATE.copy()


def update_server_state(updates):
    """Updates the server state with the given dictionary."""
    global SERVER_STATE
    SERVER_STATE.update(updates)


# Documentation (using a dictionary)
COMMAND_DOCUMENTATION = {
    "help": "Call 'help <command>' to see information about the command.\nCommands:\n\t- display\n\t- help\n\t- send\n\t- start\n\t- exit\n\t- write",
    "start": "Starts the server and logging. Takes the log file path as an argument.\nUsage: start <log_file_path>",
    "stop": "Stops the server.",
    "display": "Displays the contents of the log file.",
    "send": "Sends data using DOGProtocol.send().\nUsage: send <data>",
    "write": "Writes data directly to the log file.\nUsage: write <data>",
    "exit": "Exits the server.",
}


# --- Pure Helper Functions ---


def validate_server_running(state):
    """Validates the server state, returning an error message or None."""
    if not state["is_running"]:
        return "Server must be started first. Use the 'start' command."
    return None


def log_message(message, filepath):
    """Appends a message to the log file with timestamp."""
    try:
        with open(filepath, "a") as f:
            f.write(f"{DOG.get_timestamp()} - {message}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


# --- Command Functions ---


def help_command(args, _):
    """Displays help information."""
    command = args[1] if len(args) == 2 else None
    print(COMMAND_DOCUMENTATION.get(command, COMMAND_DOCUMENTATION["help"]))


def start_command(args, state):
    """Starts the server and logging."""
    if state["is_running"]:
        print("Server is already running.")
        return

    if len(args) != 2:
        print(COMMAND_DOCUMENTATION["start"])
        return

    filepath = args[1]

    try:
        with open(filepath, "a+"):  # Create/open log file in append mode
            pass
    except IOError as e:
        print(f"Error opening log file: {e}")
        return

    update_server_state({"is_running": True, "log_file_path": filepath})

    receive_thread = threading.Thread(target=receive_loop, daemon=True)
    receive_thread.start()

    print(f"Server started. Logging to: {filepath}")


def receive_loop():
    """Continuously receives and logs data."""
    while SERVER_STATE["is_running"]:
        try:
            received_data = DOG.receive()
            if received_data:  # Avoid logging empty data
                log_message(received_data, SERVER_STATE["log_file_path"])
        except Exception as e:
            print(f"Error in receive loop: {e}")
        finally:
            threading.event.wait(RECEIVE_INTERVAL_MS)


def send_command(args, state):
    """Sends data using DOGProtocol.send()."""
    error_message = validate_server_running(state)
    if error_message:
        print(error_message)
        return

    data = " ".join(args[1:])
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_command(args, state):
    """Writes data to the log file."""
    error_message = validate_server_running(state)
    if error_message:
        print(error_message)
        return
    message = " ".join(args[1:])
    log_message(message, SERVER_STATE["log_file_path"])
    print(f"Wrote to log: {message}")


def display_command(_, state):
    """Displays the contents of the log file."""
    error_message = validate_server_running(state)
    if error_message:
        print(error_message)
        return

    try:
        with open(SERVER_STATE["log_file_path"], "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file: {e}")


def exit_command(_, __):
    """Exits the server and cleans up GPIO."""
    update_server_state({"is_running": False})
    GPIO.cleanup()
    print("Exiting server.")
    sys.exit(0)


