COMMAND_MAP = {
    "help": help_command,
    "start": start_command,
    "stop": stop_command,
    "display": display_command,
    "send": send_command,
    "write": write_command,
    "exit": exit_command,
}


def execute_command(command_str):
    """Parses and executes a command."""
    args = command_str.split()
    if not args:
        return

    command = args[0].lower()
    func = COMMAND_MAP.get(command)
    if func:
        try:
            func(args, get_server_state())
        except Exception as e:
            print(f"Error executing command: {e}")
    else:
        print("Unknown command. Try 'help'.")


# --- Main Server Loop ---


def run_server():
    """Main server loop."""
    print("Starting DOGServer...")
    try:
        while True:
            try:
                command_str = input(PROMPT).strip()
                execute_command(command_str)
            except KeyboardInterrupt:
                print("\nKeyboard interrupt. Type 'exit' to quit.")
            except Exception as e:
                print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()  # Ensure cleanup on exit


if __name__ == "__main__":
