# Raspberry Pi script to read ambient light and control LED brightness

import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Define GPIO pin for LED control
LED_GPIO_PIN = 18

# Define PWM frequency
PWM_FREQUENCY = 1000  # Hz

# Global variable for PWM instance
pwm_instance = None

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initializes the TSL2561 light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus)
        sensor.gain = adafruit_tsl2561.GAIN_MED
        sensor.integration_time = adafruit_tsl2561.INTEGRATIONTIME_402MS
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_gpio():
    """Initializes the GPIO pin for LED control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_GPIO_PIN, GPIO.OUT)
        global pwm_instance
        pwm_instance = GPIO.PWM(LED_GPIO_PIN, PWM_FREQUENCY)
        pwm_instance.start(0)  # Start with 0% duty cycle
    except Exception as e:
        print(f"Error initializing GPIO: {e}")

def read_light_level(sensor):
    """Reads the light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def calculate_brightness(light_level):
    """Calculates the LED brightness based on the light level."""
    if light_level is None:
        return 0
    if light_level <= 0:
        return 0
    if light_level >= 1000:
        return 100
    return min(100, max(0, int(100 * (light_level - 0) / (1000 - 0))))

def set_led_brightness(brightness_percentage):
    """Sets the LED brightness using PWM."""
    try:
        pwm_instance.ChangeDutyCycle(brightness_percentage)
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def cleanup_gpio():
    """Cleans up GPIO resources."""
    try:
        if pwm_instance:
            pwm_instance.stop()
        GPIO.cleanup()
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    print("Exiting program...")
    cleanup_gpio()
    sys.exit(0)

def main():
    """Main function to read light and control LED."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        cleanup_gpio()
        sys.exit(1)

    initialize_gpio()

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is not None:
                brightness = calculate_brightness(light_level)
                set_led_brightness(brightness)
                print(f"Ambient Light: {light_level:.2f} lux, LED Brightness: {brightness}%")
            time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

