class PID:
    """
    Manages a single PID controller.
    """

    def __init__(self, data, logger, subscriptions):
        self.logger = logger
        self.data = data
        self.subscriptions = subscriptions
        self.pid = None
        self.setpoint = data.get('value', 0)
        self.last_error = 0
        self.output = 0
        self.last_time = time.time()
        self.pause_state = False


    def reset(self):
        """Resets the PID controller."""
        self.last_error = 0
        self.output = 0
        self.last_time = time.time()


    def setSetpoint(self, value):
        """Sets the setpoint."""
        self.setpoint = value


    def pause(self):
        """Pauses the PID controller."""
        self.pause_state = True


    def restart(self):
        """Restarts the PID controller."""
        self.pause_state = False


    def update(self):
        """Updates the PID controller and sends updates via subscriptions."""
        if self.pause_state:
            return

        try:
            current_time = time.time()
            dt = current_time - self.last_time

            if dt <= 0: # prevent division by zero if time goes backwards (e.g., clock adjustment)
                return

            error = self.data.get('value', 0) - self.setpoint
            self.last_error = error
            self.output = self.pid.update(error, dt)
            self.last_time = current_time

            self.broadcast_update()

        except Exception as e:
            self.logger.exception(f"Error updating PID controller: {e}")


    def broadcast_update(self):
        """Broadcasts the PID controller update via subscriptions."""
        if self.subscriptions:
            for callback in self.subscriptions:
                if not callback['control']['pause']: # Check pause state
                    try:
                        callback['callback'](self.output, **callback['kwargs'])
                    except Exception as e:
                        self.logger.exception(f"Error in PID callback: {e}")


