#!/usr/bin/env python3

"""
Raspberry Pi GPIO Monitor

This script monitors GPIO pins on a Raspberry Pi and logs changes in pin state
along with timestamps. It's designed for research purposes, focusing on robust
error handling, performance optimization, and a modular design.

Command-line arguments:
  -l, --log-file: Path to the log file (default: gpio_monitor.log).
  -d, --debounce: Debounce time in milliseconds (default: 200).
  -v, --verbose: Enable verbose output to the console.
  -c, --count: Number of GPIO pins to monitor (overrides auto-detection).
  -m, --model: Raspberry Pi model (e.g., "B+", "2", "3", "4"). Overrides auto-detection.

Hardware requirements:
  - Raspberry Pi 1 Model B, B+, 2 Model B, 3 Model B, 3 Model B+, 4 Model B
  - Jumper wires connecting GPIO pins to a breadboard (if using an external pull-up/down resistor network).
  - (Optional) External pull-up/down resistor network (10k Ohm resistors).

Example usage:
  sudo python3 gpio_monitor.py -l my_log.txt -d 300 -v
  sudo python3 gpio_monitor.py -l -d 200 -v
  sudo python3 gpio_monitor.py -c 20 -m 4
  sudo python3 gpio_monitor.py -l gpio_log.txt --model 3 B+
"""

import RPi.GPIO as GPIO
import time
import datetime
import argparse
import os
import signal
