#!/usr/bin/env python3

import time
import gpiozero

# Define the GPIO pin for the LED (BCM numbering)
LED_PIN = 17

# Define the blink rate (seconds)
BLINK_RATE = 1

def blink_led(led, duration):
    """Turns the LED on for a specified duration, then off for the same duration."""
    try:
        led.on()  # Turn the LED on
        time.sleep(duration)  # Wait for the specified duration
        led.off() # Turn the LED off
        time.sleep(duration)  # Wait for the specified duration
    except Exception as e:
        print(f"Error in blink_led: {e}")


def main():
    """Main function to blink the LED indefinitely."""
    try:
        # Initialize the LED object using gpiozero
        led = gpiozero.LED(LED_PIN)
        print(f"LED initialized on pin {LED_PIN}")

        # Blink the LED forever
        while True:
            blink_led(led, BLINK_RATE)

    except gpiozero.exc.GPIODeviceError as e:
        print(f"Error: Could not access GPIO pin {LED_PIN}. Make sure you are running as root or have appropriate permissions.")
        print(f"Details: {e}")
    except RuntimeError as e:
        print(f"Error: {e}. This likely means gpiozero is not installed or gpiozero.LED is not defined.")
    except KeyboardInterrupt:
        print("Program stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the LED is turned off and resources are released
        if 'led' in locals():
            led.off()
            led.close()
            print("LED turned off and resources released.")


if __name__ == "__main__":
    main()

