# A simple soil moisture monitoring and irrigation control script for Raspberry Pi Zero W.

import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO
from gpiozero import OutputDevice

# Define the GPIO pin connected to the relay controlling the water pump.
PUMP_PIN = 17

# Define the moisture threshold (below this value, the pump activates).
MOISTURE_THRESHOLD = 500

# Define the I2C address of the soil moisture sensor.
SEESAW_ADDRESS = 0x36

# Define the sampling interval in seconds.
SAMPLE_INTERVAL = 10


def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_seesaw(i2c_bus):
    """Initializes the Seesaw soil moisture sensor."""
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=SEESAW_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing Seesaw sensor: {e}")
        return None


def initialize_gpio(pump_pin):
    """Initializes the GPIO pin for the water pump relay."""
    try:
        pump = OutputDevice(pump_pin)
        return pump
    except Exception as e:
        print(f"Error initializing GPIO pin: {e}")
        return None


def read_moisture_level(sensor):
    """Reads the soil moisture level from the sensor."""
    try:
        moisture = sensor.moisture_read()
        return moisture
    except Exception as e:
        print(f"Error reading moisture level: {e}")
        return None


def control_water_pump(pump, moisture_level, threshold):
    """Controls the water pump based on the moisture level."""
    if moisture_level is not None:
        if moisture_level < threshold:
            pump.on()  # Activate the pump
            pump_status = "ON"
        else:
            pump.off()  # Deactivate the pump
            pump_status = "OFF"
        return pump_status
    else:
        return "Unknown"


def main():
    """Main function to run the soil moisture monitoring and irrigation control."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    sensor = initialize_seesaw(i2c_bus)
    if sensor is None:
        return  # Exit if sensor initialization failed

    pump = initialize_gpio(PUMP_PIN)
    if pump is None:
        return  # Exit if GPIO initialization failed

    try:
        while True:
            moisture = read_moisture_level(sensor)
            pump_status = control_water_pump(pump, moisture, MOISTURE_THRESHOLD)

            if moisture is not None:
                print(f"Soil Moisture: {moisture}, Pump: {pump_status}")
            else:
                print("Failed to read soil moisture.")

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the pump is off and GPIO is cleaned up on exit.
        pump.off()
        GPIO.cleanup()
        print("GPIO cleaned up. Pump deactivated.")


if __name__ == "__main__":
    main()

