from gpiozero import OutputDevice, Servo
import time

class Laser:
    def __init__(self, pin=17):
        try:
            self.laser = OutputDevice(pin)
        except Exception as e:
            print(f"Error initializing laser on pin {pin}: {e}")
            exit(1)  # Exit if laser initialization fails

    def on(self):
        self.laser.on()

    def off(self):
        self.laser.off()

    def close(self):
        self.laser.close()

class Aim:
    def __init__(self, ld, sd, hp, vp, pin1=18, pin2=19): # pin1 and pin2 are for the servos
        try:
            self.h = Servo(pin1)
            self.v = Servo(pin2)
            self.ld = ld
            self.sd = sd
            self.hp = hp
            self.vp = vp
        except Exception as e:
            print(f"Error initializing aim: {e}")
            exit(1)

    def aim(self, nums):
        try:
            for n in nums:
                self.v.value = self.vp[n-1] # corrected indexing
                self.h.value = self.hp[n-1] # corrected indexing
                time.sleep(self.sd/2)
                self.on()
                time.sleep(self.ld)
                self.off()
                self.h.value = self.hp[10] # neutral position
                self.v.value = self.vp[10] # neutral position
                time.sleep(self.sd/2)
        except Exception as e:
            print(f"Error during aiming: {e}")

    def close(self):
        self.h.close()
        self.v.close()

