DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and efficient interface for interacting with the
DS1338 RTC chip via I2C. It offers comprehensive error handling, optimized
performance, and adheres to best practices for hardware interaction.

Key Features:
- Comprehensive error handling and recovery.
- Detailed documentation with docstrings.
- Optimized for performance and resource usage.
- Best practices for hardware interaction.
- Modular and maintainable code.
"""

import smbus2 as smbus
from datetime import datetime, timedelta
import logging
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DS1338Error(Exception):
    """Base class for DS1338-specific exceptions."""
    pass


class DS1338CommunicationError(DS1338Error):
    """Raised when I2C communication fails."""
    pass


class DS1338InvalidInputError(DS1338Error):
    """Raised when input values are invalid."""
    pass


class DS1338:
    """DS1338 Real-Time Clock Driver."""

    _REG_SECONDS = 0x00
    _REG_MINUTES = 0x01
    _REG_HOURS = 0x02
    _REG_DAY = 0x03
    _REG_DATE = 0x04
    _REG_MONTH = 0x05
    _REG_YEAR = 0x06
    _REG_CONTROL = 0x07
    _REG_STATUS = 0x0F  # Added Status Register address

    def __init__(self, twi=1, addr=0x68, retry_attempts=3):
        self._bus = smbus.SMBus(twi)
        self._addr = addr
        self._retry_attempts = retry_attempts

    def _write_register(self, register, data):
        """Write data to a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                self._bus.write_byte_data(self._addr, register, data)
                return
            except (smbus.IOError, OSError) as e:
                logger.warning(f"I2C write error (attempt {attempt + 1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to write to DS1338 after multiple retries.") from e

    def _read_register(self, register):
        """Read data from a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                return self._bus.read_byte_data(self._addr, register)
            except (smbus.IOError, OSError) as e:
                logger.warning(f"I2C read error (attempt {attempt + 1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to read from DS1338 after multiple retries.") from e


    def _bcd_to_int(self, bcd):
        """Decode a 2x4bit BCD to an integer."""
        try:
            return int(str(bcd // 16) + str(bcd % 16))
        except ValueError as e:
            raise DS1338InvalidInputError(f"Invalid BCD value: {bcd}. Error: {e}") from e



    def _int_to_bcd(self, n):
        """Encode a one or two digits number to the BCD."""

        try:
            tens = int(n / 10)
            units = int(n % 10)
            return (tens * 16) + units
        except TypeError as e:
            raise DS1338InvalidInputError(f"Invalid integer value: {n}. Error: {e}") from e



    def _read_time_register(self, register):
        """Read and decode a time register (seconds, minutes, etc.)."""
        return self._bcd_to_int(self._read_register(register))

    def _read_datetime(self, century=21):
        """Read the current time from the DS1338 and return a datetime object."""
        try:
            year = self._read_time_register(self._REG_YEAR)
            month = self._read_time_register(self._REG_MONTH)
            date = self._read_time_register(self._REG_DATE)
            day = self._read_time_register(self._REG_DAY)
            hours = self._read_time_register(self._REG_HOURS) & 0x3F  # Mask 24/12h bit and reserved bits
            minutes = self._read_time_register(self._REG_MINUTES)
            seconds = self._read_time_register(self._REG_SECONDS) & 0x7F  # Mask CH bit

            return datetime(century * 100 + year, month, date, hours, minutes, seconds)

        except DS1338InvalidInputError as e:
            raise  # Re-raise the invalid input error
        except Exception as e:
            raise DS1338CommunicationError(f"Failed to read datetime: {e}") from e



    def _write_time_register(self, register, data):
        """Write a time register (seconds, minutes, etc.)."""
        self._write_register(register, self._int_to_bcd(data))


