        """Set the DS1338 time to the provided datetime object."""
        try:
            self._write_time_register(self._REG_SECONDS, dt.second)
            self._write_time_register(self._REG_MINUTES, dt.minute)
            self._write_time_register(self._REG_HOURS, dt.hour & 0x3F)  # Ensure 24-hour format
            self._write_time_register(self._REG_DATE, dt.day)
            self._write_time_register(self._REG_MONTH, dt.month)
            self._write_time_register(self._REG_YEAR, dt.year % 100)  # Store only the last two digits
            self._write_register(self._REG_CONTROL, 0x00)  # Stop clock, then start again
        except DS1338InvalidInputError as e:
            raise  # Re-raise the invalid input error
        except Exception as e:
            raise DS1338CommunicationError(f"Failed to set datetime: {e}") from e


