        """Set the DS1338 century."""
        try:
            if not 21 <= century <= 29:
                raise ValueError("Century must be between 21 and 29")
            self._write_time_register(self._REG_YEAR, century % 100)
        except ValueError as e:
            raise DS1338InvalidInputError(f"Invalid century value: {century}. Error: {e}") from e
        except Exception as e:
            raise DS1338CommunicationError(f"Failed to set century: {e}") from e

    def _get_register_value(self, register):
        """Generic function to read a register and handle potential errors."""
        try:
            return self._read_register(register)
        except DS1338CommunicationError as e:
            raise  # Re-raise the communication error


    def get_all(self):
        """Get all time registers and status register."""
        status = self._get_register_value(self._REG_STATUS)
        return (
            self._get_register_value(self._REG_SECONDS),
            self._get_register_value(self._REG_MINUTES),
            self._get_register_value(self._REG_HOURS),
            self._get_register_value(self._REG_DAY),
            self._get_register_value(self._REG_DATE),
            self._get_register_value(self._REG_MONTH),
            self._get_register_value(self._REG_YEAR),
            status,
        )

    def set_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        """Set all time registers."""

        if seconds is not None:
            self._write_time_register(self._REG_SECONDS, seconds)
        if minutes is not None:
            self._write_time_register(self._REG_MINUTES, minutes)
        if hours is not None:
            self._write_time_register(self._REG_HOURS, hours & 0x3F)
        if day is not None:
            self._write_time_register(self._REG_DAY, day)
        if date is not None:
            self._write_time_register(self._REG_DATE, date)
        if month is not None:
            self._write_time_register(self._REG_MONTH, month)
        if year is not None:
            self._write_time_register(self._REG_YEAR, year % 100)

        self._write_register(self._REG_CONTROL, 0x00)  # Stop clock, then start again



    def get_time_delta(self, dt):
        """Get the time delta between the DS1338 and the provided datetime object."""
        try:
            now = self._read_datetime()
            delta = now - dt
            return delta.total_seconds()
        except DS1338CommunicationError as e:
            raise  # Re-raise the communication error



