#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and optimized driver for the DS1338 RTC chip.
"""

import smbus2 as smbus
from datetime import datetime, timezone
import contextlib

def _bcd_to_int(bcd):
    """Decode a 2x4bit BCD value to an integer."""
    try:
        return int(f"{bcd >> 4:01}{bcd & 0x0F:01}")
    except ValueError:
        raise ValueError("Invalid BCD value")


def _int_to_bcd(n):
    """Encode an integer to BCD format."""
    try:
        tens, units = divmod(n, 10)
        return (tens << 4) | units
    except TypeError:
        raise ValueError("Invalid integer value")


class DS1338:
    """DS1338 Real-Time Clock Driver."""

    _REG_SECONDS = 0x00
    _REG_MINUTES = 0x01
    _REG_HOURS = 0x02
    _REG_DAY = 0x03
    _REG_DATE = 0x04
    _REG_MONTH = 0x05
    _REG_YEAR = 0x06
    _REG_CONTROL = 0x07

    def __init__(self, twi=1, addr=0x68):
        """Initialize the DS1338 driver."""
        try:
            self._bus = smbus.SMBus(twi)
        except Exception as e:
            raise IOError(f"Failed to open I2C bus: {e}")

        self._addr = addr

    def _write_register(self, register, data):
        """Write data to a specific register."""
        try:
            self._bus.write_byte_data(self._addr, register, data)
        except Exception as e:
            raise IOError(f"Failed to write to register {register:#04x}: {e}")

    def _read_register(self, register):
        """Read data from a specific register."""
        try:
            return self._bus.read_byte_data(self._addr, register)
        except Exception as e:
            raise IOError(f"Failed to read from register {register:#04x}: {e}")

    def read_all(self):
        """Read all time registers and return as a tuple."""
        try:
            year = self._bcd_to_int(self._read_register(self._REG_YEAR))
            month = self._bcd_to_int(self._read_register(self._REG_MONTH))
            date = self._bcd_to_int(self._read_register(self._REG_DATE))
            day = self._bcd_to_int(self._read_register(self._REG_DAY))
            hours = self._bcd_to_int(self._read_register(self._REG_HOURS) & 0x3F)
            minutes = self._bcd_to_int(self._read_register(self._REG_MINUTES))
            seconds = self._bcd_to_int(self._read_register(self._REG_SECONDS) & 0x7F)
            return year, month, date, day, hours, minutes, seconds
        except Exception as e:
            raise IOError(f"Failed to read all RTC data: {e}")


    def read_datetime(self, century=21):
        """Read the current time and return as a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year
            return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
        except Exception as e:
            raise IOError(f"Failed to convert RTC data to datetime: {e}")


    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all time registers."""

        if not 1900 <= year <= 2099:
            raise ValueError("Year must be between 1900 and 2099")
        if not 1 <= month <= 12:             raise ValueError("Month must be between 1 and 12")
        if not 1 <= date <= 31:             raise ValueError("Date must be between 1 and 31")
        if not 1 <= day <= 7:             raise ValueError("Day must be between 1 and 7")
        if not 0 <= hours <= 23:            raise ValueError("Hours must be between 0 and 23")
        if not 0 <= minutes <= 59:          raise ValueError("Minutes must be between 0 and 59")
        if not 0 <= seconds <= 59:          raise ValueError("Seconds must be between 0 and 59")

        self._write_register(self._REG_SECONDS, _int_to_bcd(seconds))
        self._write_register(self._REG_MINUTES, _int_to_bcd(minutes))
        self._write_register(self._REG_HOURS, _int_to_bcd(hours))  # Ensure 24-hour mode
        self._write_register(self._REG_DAY, _int_to_bcd(day))
        self._write_register(self._REG_DATE, _int_to_bcd(date))
        self._write_register(self._REG_MONTH, _int_to_bcd(month))
        self._write_register(self._REG_YEAR, _int_to_bcd(year % 100)) # Store only last two digits


    def write_datetime(self, dt):
        """Write time from a datetime object."""
        if not dt.tzinfo:
            raise ValueError("Datetime object must have timezone information.")

        self.write_all(
            dt.year % 100,
            dt.month,
            dt.day,
            dt.isoweekday(),  # Day of week (1-7, Monday=1)
            dt.hour,
            dt.minute,
            dt.second,
        )

    def close(self):
        """Close the I2C bus."""
        if self._bus:
            self._bus.close()


@contextlib.contextmanager
def ds1338(twi=1, addr=0x68):
    """Context manager for DS1338 resource management."""
    ds = DS1338(twi, addr)
    try:
        yield ds
    finally:
        ds.close()


def main():
    """Main function to demonstrate DS1338 usage."""
    try:
        with ds1338() as ds:
            current = ds.read_datetime()
            print(f"Current time: {current}")
            dt = datetime(2025, 1, 1, 10, 30, 0, tzinfo=timezone.utc)
            ds.write_datetime(dt)
            print(f"Set time to: {dt}")
    except Exception as e:
        print(f"Error: {e}")



if __name__ == "__main__":
    main()

