RTC_ADDRESS = 0x68

def load_config(config_file="irrigation_config.json"):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        logging.info("Configuration loaded successfully.")
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error(f"Error decoding JSON in {config_file}")
        return DEFAULT_CONFIG

def get_rtc_time():
    """Reads the current time from the DS3231 RTC."""
    try:
        bus = smbus2.SMBus(1)  # Use I2C bus 1
        data = bus.read_i2c_block_data(RTC_ADDRESS, 0x00, 7)
        seconds = bcd_to_decimal(data[0] & 0x7F)
        minutes = bcd_to_decimal(data[1])
        hours = bcd_to_decimal(data[2] & 0x3F)
        logging.info("Time read from RTC.")
        return datetime(2022, 8, 22, hours, minutes, seconds) # Hardcoded date for testing
    except Exception as e:
        logging.error(f"Error reading from RTC: {e}")
        logging.warning("Falling back to system time.")
        return datetime.now()

def bcd_to_decimal(bcd):
    """Converts a BCD value to decimal."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def transmit_rf_code(code, gpio_pin, transmission_repeat):
    """Transmits an RF code using the 433MHz transmitter."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.OUT)

        for _ in range(transmission_repeat):
            for bit in code:
                if bit == '1':
                    GPIO.output(gpio_pin, GPIO.HIGH)
                else:
                    GPIO.output(gpio_pin, GPIO.LOW)
                time.sleep(0.001)  # 1ms pulse
            time.sleep(0.01) # 10ms gap between repeats
        logging.info(f"RF code '{code}' transmitted successfully.")
    except Exception as e:
        logging.error(f"Error transmitting RF code: {e}")
    finally:
        GPIO.cleanup(gpio_pin)

def main():
    """Main function to control the irrigation system."""
    parser = argparse.ArgumentParser(description="Control an irrigation system using RF codes.")
    parser.add_argument("zone", nargs="?", choices=["zone1", "zone2"], help="Zone to control (zone1 or zone2)")
    parser.add_argument("state", nargs="?", choices=["on", "off"], help="State to set (on or off)")
    args = parser.parse_args()

    config = load_config()

    try:
        if args.zone and args.state:
            if args.zone == "zone1":
                if args.state == "on":
                    code = config["zone1_on_code"]
                    logging.info("Turning on zone 1.")
                else:
                    code = config["zone1_off_code"]
                    logging.info("Turning off zone 1.")
            elif args.zone == "zone2":
                if args.state == "on":
                    code = config["zone2_on_code"]
                    logging.info("Turning on zone 2.")
                else:
                    code = config["zone2_off_code"]
                    logging.info("Turning off zone 2.")
            else:
                raise ValueError("Invalid zone specified.")

            transmit_rf_code(code, config["gpio_pin"], config["transmission_repeat"])
        else:
            rtc_time = get_rtc_time()
            logging.info(f"Current time: {rtc_time.strftime('%Y-%m-%d %H:%M:%S')}")

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        GPIO.cleanup() # Ensure GPIO is cleaned up even if errors occur

if __name__ == "__main__":
    main()

