import serial
import time
from gpiozero import LED

# Configuration constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1  # seconds

def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_alarm_led(pin):
    """Initializes and returns an LED object for the alarm pin."""
    try:
        return LED(pin)
    except Exception as e:
        print(f"Error initializing alarm LED: {e}")
        return None

def read_radiation_data(serial_port):
    """Reads a line of data from the serial port and returns it as a float."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Error: Non-numeric data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading data: {e}")
        return None

def trigger_alarm(led, is_active):
    """Activates or deactivates the alarm LED based on the radiation level."""
    if led:
        led.value = 1 if is_active else 0

def main():
    """Main function to read radiation data and control the alarm."""
    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_port is None:
        exit(1)

    alarm_led = initialize_alarm_led(ALARM_GPIO_PIN)
    if alarm_led is None:
        serial_port.close()
        exit(1)

    try:
        while True:
            radiation_level = read_radiation_data(serial_port)

            if radiation_level is not None:
                print(f"Radiation Level: {radiation_level} µSv/h")

                if radiation_level > RADIATION_THRESHOLD:
                    print("ALARM: Radiation level exceeded threshold!")
                    trigger_alarm(alarm_led, True)  # Activate alarm
                else:
                    trigger_alarm(alarm_led, False)  # Deactivate alarm

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        # Ensure resources are released
        if serial_port:
            serial_port.close()
        if alarm_led:
            alarm_led.close()
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

