"""
Reads power consumption data from a smart energy meter via UART on a Raspberry Pi.
"""

import serial
import time
import logging

# Configure logging
logging.basicConfig(filename='power_consumption.log', level=logging.INFO,
                    format='%(asctime)s - Power: %(message)s W')

# Serial port configuration
SERIAL_PORT = '/dev/serial0'  # UART port on Raspberry Pi
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

def read_power_data():
    """Reads power consumption data from the serial port."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            logging.info(f"Connected to serial port: {SERIAL_PORT}")
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            power_watts = float(line)
                            logging.info(f"Power consumption: {power_watts} W")
                        except ValueError:
                            logging.error(f"Invalid data received: {line}")
                            print(f"Warning: Invalid data received: {line}") # Print to console as well
                except serial.SerialException as e:
                    logging.error(f"Serial communication error: {e}")
                    break  # Exit the loop on serial error
                except Exception as e:
                    logging.error(f"An unexpected error occurred: {e}")
                    break # Exit the loop on unexpected error
                time.sleep(0) # Reduce CPU usage
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except OSError as e:
        logging.error(f"OS error while accessing serial port: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred during initialization: {e}")

def main():
    """Main function to read and log power data."""
    try:
        read_power_data()
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An error occurred in main: {e}")
    finally:
        logging.info("Exiting program.")

if __name__ == "__main__":
    main()

