# -*- coding: utf-8 -*-

"""
Simple Flask-Restplus API for SCPI Instrument Control (Beginner-Friendly)
"""

import json
import time
from threading import Thread
from flask import Flask, Response, request, jsonify, abort
from flask_restplus import Api, Resource
import serial

# Initialize Flask app and API
app = Flask(__name__)
api = Api(app)

# Global data store (in-memory)
data_store = []

# Serial port configuration (default)
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Initialize serial port
try:
    serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    serial_port = None  # Set to None if initialization fails


# --- Helper Functions ---

def get_serial_port():
    """Returns the serial port object if available, otherwise None."""
    return serial_port


def send_scpi_command(command):
    """Sends an SCPI command to the instrument and reads the response."""
    if serial_port is None:
        print("Serial port not available.")
        return None

    try:
        serial_port.write(command.encode())
        response = serial_port.readline().decode().strip()
        return response
    except serial.SerialException as e:
        print(f"Error communicating with serial port: {e}")
        return None


# --- API Resources ---

@api.route('/version')
def get_instrument_version():
    """Retrieves the instrument version information via *IDN?."""
    if serial_port is None:
        return Response("Serial port not available.", mimetype='text/plain', status=503)

    command = '*IDN?\n'
    response = send_scpi_command(command)

    if response:
        return Response(response + "\n", mimetype='text/html')
    else:
        return Response("Failed to get version information.", mimetype='text/plain', status=503)


